<template>
  <div class="page-shell"><div class="page-heading"><div><h1>消息中心</h1><p>审核结果、巡查任务和重要公告都会汇集到这里。</p></div><el-button :disabled="!auth.unreadCount" @click="readAll"><el-icon><CircleCheck/></el-icon>全部已读</el-button></div><section class="panel"><div class="toolbar"><el-select v-model="query.isRead" clearable placeholder="阅读状态" style="width:140px"><el-option label="未读" :value="0"/><el-option label="已读" :value="1"/></el-select><el-select v-model="query.type" clearable placeholder="消息类型" style="width:150px"><el-option v-for="(v,k) in types" :key="k" :label="v" :value="k"/></el-select><el-button @click="load"><el-icon><Search/></el-icon>筛选</el-button></div><div class="message-list" v-loading="loading"><article v-for="item in page.records" :key="item.id" :class="{unread:!item.isRead}" @click="open(item)"><div class="message-icon" :class="item.type"><el-icon><component :is="iconMap[item.type]||'Bell'"/></el-icon></div><div class="message-body"><div><b>{{item.title}}</b><el-tag v-if="!item.isRead" size="small" type="danger">未读</el-tag></div><p>{{item.content}}</p><small>{{item.createdAt}} · {{types[item.type]||'系统消息'}}</small></div><el-button circle text @click.stop="remove(item.id)"><el-icon><Delete/></el-icon></el-button></article><el-empty v-if="!page.records.length" description="暂时没有消息"/><div class="pagination"><el-pagination v-model:current-page="query.pageNum" :total="page.total" layout="total,prev,pager,next" @current-change="load"/></div></div></section></div>
</template>
<script setup>
import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{useRouter}from'vue-router';import http from'../api/http';import{useAuthStore}from'../stores/auth';const auth=useAuthStore(),router=useRouter(),types={AUDIT:'审核通知',PERMIT:'居住证',PATROL:'巡查任务',NOTICE:'重要公告',SYSTEM:'系统消息'},iconMap={AUDIT:'DocumentChecked',PERMIT:'Postcard',PATROL:'Location',NOTICE:'Notification',SYSTEM:'Bell'},query=reactive({pageNum:1,pageSize:10,isRead:null,type:''}),page=reactive({records:[],total:0}),loading=ref(false);onMounted(load);async function load(){loading.value=true;try{Object.assign(page,await http.get('/messages',{params:query}));auth.loadUnread()}finally{loading.value=false}}async function open(item){if(!item.isRead)await http.put(`/messages/${item.id}/read`);const route={TENANCY:'/tenancies',PERMIT:'/permits',PATROL:'/patrols',NOTICE:'/notices',OWNER_APPLICATION:'/owner-applications'}[item.businessType];if(route)router.push(route);else load()}async function readAll(){await http.put('/messages/read-all');ElMessage.success('全部消息已标记为已读');load()}async function remove(id){await http.delete(`/messages/${id}`);ElMessage.success('消息已删除');load()}
</script>
<style scoped>.message-list{padding:8px 18px 18px}.message-list article{display:flex;align-items:flex-start;gap:14px;padding:18px 10px;border-bottom:1px solid #edf2f3;cursor:pointer}.message-list article:hover{background:#f7fafa}.message-list article.unread{background:#f5fbfa}.message-icon{width:42px;height:42px;border-radius:11px;display:grid;place-items:center;background:#e9f0f3;color:#173c57;font-size:19px}.message-icon.AUDIT,.message-icon.PERMIT{background:#fff0d9;color:#c98725}.message-icon.PATROL{background:#def2ee;color:#0e8a7a}.message-icon.NOTICE{background:#e7edf7;color:#355c98}.message-body{flex:1}.message-body>div{display:flex;align-items:center;gap:8px}.message-body b{font-size:13px}.message-body p{font-size:12px;color:#617987;line-height:1.7;margin:7px 0}.message-body small{color:#9aaab2;font-size:10px}</style>
